379	/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
380	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
381	
382	/** The status changes a claim can be asked for, as named in the store's API. */
383	export type ClaimAction = 'open' | 'settle' | 'void';
