385	/**
386	 * Whether the claim counts toward claimed, due-total and every total: an OPEN or SETTLED one, but
387	 * not an OPEN one while its person is on hold.
388	 */
389	export function counts(claim: Claim, person: { held: boolean }): boolean {
390	  return claim.status === 'SETTLED' || (claim.status === 'OPEN' && !person.held);
391	}
