393	/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian), without reading any clock. */
394	function epochDay(date: string): number {
395	  const [y0, m, d] = date.split('-').map(Number);
396	  const y = m <= 2 ? y0 - 1 : y0;
397	  const era = Math.floor(y / 400);
398	  const yoe = y - era * 400;
399	  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
400	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
401	  return era * 146097 + doe - 719468;
402	}
403	
404	/** The yyyy-mm-dd date of a count of days since 1970-01-01. */
405	function fromEpochDay(days: number): string {
406	  const z = days + 719468;
407	  const era = Math.floor(z / 146097);
408	  const doe = z - era * 146097;
409	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
410	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
411	  const mp = Math.floor((5 * doy + 2) / 153);
412	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
413	  const m = mp < 10 ? mp + 3 : mp - 9;
414	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
415	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
416	}
417	
418	/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
419	export function dueBy(claim: Claim, terms: number): string {
420	  return fromEpochDay(epochDay(claim.date) + terms);
421	}
422	
423	/** Whether the claim is overdue: OPEN, with its due-by before the sheet's today. */
424	export function overdue(claim: Claim, terms: number, today: string): boolean {
425	  return claim.status === 'OPEN' && dueBy(claim, terms) < today;
426	}
427	
428	/** How many days the claim's due-by is before the sheet's today; 0 when it is not. */
429	export function daysOverdue(claim: Claim, terms: number, today: string): number {
430	  return Math.max(0, epochDay(today) - epochDay(claim.date) - terms);
431	}
