441	/** An amount the store accepts: 0 or more, with at most two decimals. */
442	export const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;
443	
444	/** A claim amount the store accepts: at most two decimals; a negative one is a correction. */
445	export const CLAIM_AMOUNT = /^-?\d{1,10}(\.\d{1,2})?$/;
446	
447	/** A claim number, as typed in the claim form's corrects field. */
448	export const CLAIM_NUMBER = /^\d{1,15}$/;
449	
450	/** Whether the claim is a correction: its amount is below 0. */
451	export function isCorrection(claim: { amount: string }): boolean {
452	  return claim.amount.trim().startsWith('-') && toCents(claim.amount) !== 0;
453	}
454	
455	/** Whole cents of a valid amount (negative for a correction), so sums are exact. */
456	export function toCents(amount: string): number {
457	  const negative = amount.trim().startsWith('-');
458	  const [whole, frac = ''] = amount.trim().replace(/^-/, '').split('.');
459	  const cents = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
460	  return negative ? -cents : cents;
461	}
462	
463	export function formatCents(cents: number): string {
464	  const abs = Math.abs(cents);
465	  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
466	}
