468	// The claims kept on the active sheet, newest first, read from and written to the store.
469	@Injectable({ providedIn: 'root' })
470	export class Claims {
471	  private readonly http = inject(HttpClient);
472	  private readonly session = inject(Session);
473	
474	  readonly all = signal<Claim[]>([]);
475	
476	  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
477	  async reload(): Promise<void> {
478	    this.all.set([]);
479	    try {
480	      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
481	    } catch {
482	      this.all.set([]);
483	    }
484	  }
485	
486	  async add(personId: number, fields: ClaimFields): Promise<void> {
487	    const added = await firstValueFrom(
488	      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
489	    );
490	    this.all.update((list) => [added, ...list]);
491	  }
492	
493	  /**
494	   * The quick-add bar: a DRAFT claim of the amount, dated the sheet's today, for the person of the
495	   * name; the store adds the person first (grade A) when the name is not on the sheet.
496	   */
497	  async quickAdd(name: string, amount: string): Promise<Claim> {
498	    const added = await firstValueFrom(
499	      this.http.post<Claim>(`${this.sheetUrl()}/quick-add`, { name, amount: amount.trim() }, { headers: this.headers() }),
500	    );
501	    this.all.update((list) => [added, ...list]);
502	    return added;
503	  }
504	
505	  async update(id: number, fields: ClaimFields): Promise<void> {
506	    const saved = await firstValueFrom(
507	      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
508	    );
509	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
510	  }
511	
512	  /** Move a claim to its next status; the store refuses a change its status does not allow. */
513	  async act(id: number, action: ClaimAction): Promise<void> {
514	    const saved = await firstValueFrom(
515	      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
516	    );
517	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
518	  }
519	
520	  private body(fields: ClaimFields) {
521	    const corrects = fields.corrects.trim();
522	    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note, corrects: corrects ? Number(corrects) : null };
523	  }
524	
525	  private sheetUrl(): string {
526	    const id = this.session.sheetId();
527	    if (!id) throw new Error('no sheet loaded');
528	    return `/api/sheets/${encodeURIComponent(id)}`;
529	  }
530	
531	  private headers(): Record<string, string> {
532	    const user = this.session.user();
533	    if (!user) throw new Error('not signed in');
534	    return { 'X-User': user };
535	  }
536	}
