739	        this.error.set(NOT_CORRECTING);
740	        return;
741	      }
742	    } else {
743	      fields.corrects = '';
744	    }
745	    if (this.periods.closedOn(fields.date || (this.session.today() ?? ''))) {
746	      this.error.set(CLOSED);
747	      return;
748	    }
749	    if (retiredOn({ retiredFrom: this.retiredFrom() }, fields.date || (this.session.today() ?? ''))) {
750	      this.error.set(RETIRED);
751	      return;
752	    }
753	    const id = this.editingId();
754	    this.saving = true;
755	    try {
756	      if (id === null) {
757	        await this.claims.add(this.personId(), fields);
758	      } else {
759	        await this.claims.update(id, fields);
760	      }
761	      this.reset();
762	    } catch (e) {
763	      this.error.set(e instanceof HttpErrorResponse && e.status === 423
764	        ? CLOSED
765	        : e instanceof HttpErrorResponse && e.status === 409
766	        ? NOT_DRAFT
767	        : e instanceof HttpErrorResponse && e.status === 422
768	        ? isCorrection(fields) ? NOT_CORRECTING : RETIRED
769	        : id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
770	    } finally {
771	      this.saving = false;
772	    }
773	  }
774	}
