package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
 * status (423). No claim dated after its person's retirement date can be added or edited (422).
 * A claim with a negative amount is a correction: it must name, by number, a SETTLED claim of the
 * same person, or it is refused (422); a claim that is not a correction names none.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final PeriodRepository periods;
    private final RateService rates;
    private final RoleService roles;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, PeriodRepository periods, RateService rates,
            RoleService roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.claims = claims;
        this.people = people;
        this.periods = periods;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            Long corrects) {
        sheets.load(sheetId, user);
        // Lock the sheet, so a period closed at the same moment is seen.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseIfClosed(sheetId, on);
        refuseIfRetired(person, on);
        Long corrected = correctedNumber(sheetId, personId, amount, corrects);
        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : "", corrected));
        record("CLAIM_ADDED", user, person, claim);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note,
            Long corrects) {
        sheets.lock(sheetId);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
        }
        refuseIfClosed(sheetId, claim.getDate());
        refuseIfClosed(sheetId, on);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        refuseIfRetired(person, on);
        Long corrected = correctedNumber(sheetId, person.getId(), amount, corrects);
        claim.setAmount(scaled(amount));
        claim.setCorrects(corrected);
        claim.setDate(on);
        claim.setNote(note != null ? note : "");
        record("CLAIM_EDITED", user, person, claim);
        return claim;
    }

    /**
     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
     * gives the claim the sheet's next number; a voided claim keeps it (the number is never given again).
     * Opening records who opened it; that user cannot settle it (403).
     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
     * leave it as fixed. Every rounding is half up for a claim dated before the sheet's policy date and
     * half to even otherwise; later policy date changes leave it as fixed too. A correction's due is its amount times that rate, rounded the same way, with no
     * floor and no late charge. A clerk
     * can settle a claim only when that due is at or below the sheet's clerk limit, if it has one (403);
     * a claim with no due (no rate) is then refused too, as it cannot be shown to be within the limit.
     * A steward settles any claim.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
        // and a period closed at the same moment is seen.
        Sheet sheet = sheets.lock(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        refuseIfClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        List<String> extra = new ArrayList<>();
        if (next == ClaimStatus.SETTLED) {
            BigDecimal due = sheet.liveDue(rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                    .map(rate -> sheet.dueAt(claim.getAmount(), rate.getRate(), claim.getDate()))
                    .orElse(null), claim.getDate(), claim.isCorrection());
            refuseIfOverClerkLimit(sheet, user, due);
            claim.setSettledDue(due);
            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
        }
        record(switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        }, user, person, claim, number, extra);
        return claim;
    }

    /**
     * The number a claim corrects: for a negative amount, the number of a SETTLED claim of the same
     * person, refused (422) when none is named or it names no such claim; none for any other amount.
     */
    private Long correctedNumber(String sheetId, Long personId, BigDecimal amount, Long corrects) {
        if (amount.signum() >= 0) {
            return null;
        }
        boolean settled = corrects != null && claims.findFirstBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED)
                .isPresent();
        if (!settled) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A negative amount must correct a settled claim of the same person");
        }
        return corrects;
    }

    /** Refuse (403) a clerk settling a claim whose due is above the sheet's clerk limit. */
    private void refuseIfOverClerkLimit(Sheet sheet, String user, BigDecimal due) {
        BigDecimal limit = sheet.getClerkLimit();
        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
            return;
        }
        if (due == null || due.compareTo(limit) > 0) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "A clerk cannot settle a claim with a due above " + limit.toPlainString());
        }
    }

    /** Refuse (423) a change to a claim dated in a closed period. */
    private void refuseIfClosed(String sheetId, LocalDate date) {
        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(period -> period.isClosed() && period.contains(date))
                .findFirst()
                .ifPresent(period -> {
                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
                });
    }

    /** Refuse (422) a claim dated after its person's retirement date. */
    private static void refuseIfRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    person.getName() + " is retired from " + person.getRetiredFrom());
        }
    }

    private void record(String event, String user, Person person, Claim claim) {
        record(event, user, person, claim, claim.getNumber(), List.of());
    }

    /**
     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
     */
    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
        if (number != null) {
            fields.add("number=" + number);
        }
        fields.addAll(extra);
        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
    }

    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** Claims on a sheet. The signed-in user's name is sent in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * The amount is sent as text with exactly two decimals, so it is never rounded as a float; so is
     * the due fixed when the claim was settled (null if it is not settled or had no rate then).
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, Long number, String settledDue, String openedBy, Long corrects) {
        static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.getCorrects());
        }
    }

    /**
     * The amount has at most two decimals; a negative one is a correction, which names the number of
     * the settled claim it corrects. A missing date is the sheet's today.
     */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "-?\\d{1,10}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            Long corrects) {
    }

    /** The quick-add bar: a name (stored trimmed) and an amount, with the rules of the person and claim forms. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String amount) {
    }

    private final ClaimService service;
    private final QuickAddService quickAdd;

    public ClaimController(ClaimService service, QuickAddService quickAdd) {
        this.service = service;
        this.quickAdd = quickAdd;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ClaimRequest request) {
        return ClaimView.of(service.add(sheetId.trim(), user.trim(), personId,
                new BigDecimal(request.amount()), request.date(), request.note(), request.corrects()));
    }

    @PostMapping("/quick-add")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView quickAdd(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated QuickAddRequest request) {
        return ClaimView.of(quickAdd.add(sheetId.trim(), user.trim(), request.name(), new BigDecimal(request.amount())));
    }

    @PutMapping("/claims/{claimId}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ClaimRequest request) {
        return ClaimView.of(service.update(sheetId.trim(), user.trim(), claimId,
                new BigDecimal(request.amount()), request.date(), request.note(), request.corrects()));
    }

    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.VOID));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    Optional<Claim> findFirstBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, Long number);
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Always with two decimals, e.g. "2.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number given when the claim was opened; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** The due fixed when the claim was settled, two decimals; null if not settled or it had no rate then. */
  settledDue: string | null;
  /** The user who opened the claim; null while it has not been opened. That user cannot settle it. */
  openedBy: string | null;
  /** The number of the settled claim this correction (a negative amount) corrects; null for any other claim. */
  corrects: number | null;
}

/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a claim can be asked for, as named in the store's API. */
export type ClaimAction = 'open' | 'settle' | 'void';

/**
 * Whether the claim counts toward claimed, due-total and every total: an OPEN or SETTLED one, but
 * not an OPEN one while its person is on hold.
 */
export function counts(claim: Claim, person: { held: boolean }): boolean {
  return claim.status === 'SETTLED' || (claim.status === 'OPEN' && !person.held);
}

/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian), without reading any clock. */
function epochDay(date: string): number {
  const [y0, m, d] = date.split('-').map(Number);
  const y = m <= 2 ? y0 - 1 : y0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** The yyyy-mm-dd date of a count of days since 1970-01-01. */
function fromEpochDay(days: number): string {
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  return fromEpochDay(epochDay(claim.date) + terms);
}

/** Whether the claim is overdue: OPEN, with its due-by before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string): boolean {
  return claim.status === 'OPEN' && dueBy(claim, terms) < today;
}

/** How many days the claim's due-by is before the sheet's today; 0 when it is not. */
export function daysOverdue(claim: Claim, terms: number, today: string): number {
  return Math.max(0, epochDay(today) - epochDay(claim.date) - terms);
}

export interface ClaimFields {
  amount: string;
  date: string;
  note: string;
  /** The number of the settled claim a correction corrects, as typed; empty for none. */
  corrects: string;
}

/** An amount the store accepts: 0 or more, with at most two decimals. */
export const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;

/** A claim amount the store accepts: at most two decimals; a negative one is a correction. */
export const CLAIM_AMOUNT = /^-?\d{1,10}(\.\d{1,2})?$/;

/** A claim number, as typed in the claim form's corrects field. */
export const CLAIM_NUMBER = /^\d{1,15}$/;

/** Whether the claim is a correction: its amount is below 0. */
export function isCorrection(claim: { amount: string }): boolean {
  return claim.amount.trim().startsWith('-') && toCents(claim.amount) !== 0;
}

/** Whole cents of a valid amount (negative for a correction), so sums are exact. */
export function toCents(amount: string): number {
  const negative = amount.trim().startsWith('-');
  const [whole, frac = ''] = amount.trim().replace(/^-/, '').split('.');
  const cents = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return negative ? -cents : cents;
}

export function formatCents(cents: number): string {
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// The claims kept on the active sheet, newest first, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly all = signal<Claim[]>([]);

  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
  async reload(): Promise<void> {
    this.all.set([]);
    try {
      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
    } catch {
      this.all.set([]);
    }
  }

  async add(personId: number, fields: ClaimFields): Promise<void> {
    const added = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => [added, ...list]);
  }

  /**
   * The quick-add bar: a DRAFT claim of the amount, dated the sheet's today, for the person of the
   * name; the store adds the person first (grade A) when the name is not on the sheet.
   */
  async quickAdd(name: string, amount: string): Promise<Claim> {
    const added = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/quick-add`, { name, amount: amount.trim() }, { headers: this.headers() }),
    );
    this.all.update((list) => [added, ...list]);
    return added;
  }

  async update(id: number, fields: ClaimFields): Promise<void> {
    const saved = await firstValueFrom(
      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  /** Move a claim to its next status; the store refuses a change its status does not allow. */
  async act(id: number, action: ClaimAction): Promise<void> {
    const saved = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  private body(fields: ClaimFields) {
    const corrects = fields.corrects.trim();
    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note, corrects: corrects ? Number(corrects) : null };
  }

  private sheetUrl(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, linkedSignal, signal } from '@angular/core';
import { CLAIM_AMOUNT, CLAIM_NUMBER, Claim, ClaimAction, Claims, dueBy, formatCents, isCorrection, overdue } from '../../core/claims';
import { GradeFrom, gradeOn, retiredOn } from '../../core/people';
import { Periods } from '../../core/periods';
import { Rates } from '../../core/rates';
import { Session } from '../../core/session';

const CLOSED = 'The claim is dated in a closed period, so it cannot be changed.';
const RETIRED = 'The person is retired before that date, so no claim can be dated then.';
const NOT_CORRECTING = 'A negative amount is a correction: name the number of a settled claim of this person that it corrects.';
const NOT_DRAFT = 'Only a draft claim can be edited. To change an open claim, void it and add a new one.';

// One person's claims, newest first, and the one form that adds a claim or edits an existing one.
@Component({
  selector: 'app-person-claims',
  template: `
    <form (submit)="save($event)" [attr.aria-label]="'Claim for ' + personName()">
      <label [for]="'claim-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-amount-' + personId()"
        inputmode="decimal"
        data-testid="claim-form-amount"
        [value]="amount()"
        (input)="amount.set($any($event.target).value); error.set(null)"
      />
      <label [for]="'claim-date-' + personId()">Date</label>
      <input
        [id]="'claim-date-' + personId()"
        type="date"
        data-testid="claim-form-date"
        [value]="date()"
        (input)="date.set($any($event.target).value); error.set(null)"
      />
      <label [for]="'claim-note-' + personId()">Note</label>
      <input
        [id]="'claim-note-' + personId()"
        data-testid="claim-form-note"
        [value]="note()"
        (input)="note.set($any($event.target).value); error.set(null)"
      />
      <label [for]="'claim-corrects-' + personId()">Corrects claim number</label>
      <input
        [id]="'claim-corrects-' + personId()"
        inputmode="numeric"
        data-testid="claim-form-corrects"
        [value]="corrects()"
        (input)="corrects.set($any($event.target).value); error.set(null)"
      />
      <button type="submit" data-testid="claim-form-submit">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editingId() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error(); as err) {
        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
      }
    </form>

    <ul>
      @for (c of mine(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <span data-testid="claim-number">{{ c.number }}</span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-due">{{ due(c) }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-due-by">{{ dueBy(c) }}</span>
          <span data-testid="claim-overdue">{{ overdue(c) ? 'yes' : 'no' }}</span>
          <span data-testid="claim-period">{{ periods.on(c.date)?.name }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span data-testid="claim-corrects">{{ c.corrects }}</span>
          <span data-testid="claim-status">{{ c.status }}</span>
          <span data-testid="claim-opened-by">{{ c.openedBy }}</span>
          <button type="button" data-testid="claim-edit" (click)="edit(c)">
            Edit<span class="visually-hidden"> claim of {{ c.amount }} on {{ c.date }}</span>
          </button>
          @for (a of actions; track a.action) {
            <button type="button" [attr.data-testid]="'claim-' + a.action" (click)="act(c, a.action)">
              {{ a.label }}<span class="visually-hidden"> claim of {{ c.amount }} on {{ c.date }}</span>
            </button>
          }
          @if (rowError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ rowError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly claims = inject(Claims);
  private readonly session = inject(Session);
  private readonly rates = inject(Rates);
  protected readonly periods = inject(Periods);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** The person's grades, each with the date it applies from; a claim uses the one in force on its date. */
  readonly grades = input.required<GradeFrom[]>();
  /** yyyy-mm-dd the person is retired from, or null; a claim dated after it is refused. */
  readonly retiredFrom = input<string | null>(null);

  protected readonly mine = computed(() => this.claims.all().filter((c) => c.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly date = linkedSignal(() => this.session.today() ?? '');
  protected readonly note = signal('');
  /** The number of the settled claim a correction corrects, as typed. */
  protected readonly corrects = signal('');
  protected readonly editingId = signal<number | null>(null);
  /** Set while a submit awaits the store, so a second submit does not store a second claim. */
  private saving = false;
  protected readonly error = signal<string | null>(null);
  /** The error of the last action taken on a claim's row, if it was refused. */
  protected readonly rowError = signal<{ id: number; message: string } | null>(null);

  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  /**
   * A settled claim's due as fixed when it was settled; any other claim's due at its person's grade (in force on
   * the claim's date)'s rate in force on the claim's date. n/a when there was or is no such rate.
   */
  protected due(claim: Claim): string {
    const cents = this.rates.dueOf(claim, gradeOn(this.grades(), claim.date));
    return cents === undefined ? 'n/a' : formatCents(cents);
  }

  /** The claim's due-by: its date plus the sheet's terms. */
  protected dueBy(claim: Claim): string {
    return dueBy(claim, this.session.terms() ?? 14);
  }

  /** Whether the claim is OPEN with its due-by before the sheet's today. */
  protected overdue(claim: Claim): boolean {
    return overdue(claim, this.session.terms() ?? 14, this.session.today() ?? '');
  }

  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
    this.rowError.set(null);
    if (this.periods.closedOn(claim.date)) {
      this.rowError.set({ id: claim.id, message: CLOSED });
      return;
    }
    try {
      await this.claims.act(claim.id, action);
    } catch (e) {
      const message = e instanceof HttpErrorResponse && e.status === 423
        ? CLOSED
        : e instanceof HttpErrorResponse && e.status === 403
        ? claim.openedBy === this.session.user()
          ? 'The user who opened a claim cannot settle it.'
          : `A clerk cannot settle a claim with a due above ${this.session.clerkLimit()}.`
        : `A ${claim.status} claim cannot be changed that way.`;
      this.rowError.set({ id: claim.id, message });
    }
  }

  protected edit(claim: Claim): void {
    this.rowError.set(null);
    if (this.periods.closedOn(claim.date)) {
      this.reset();
      this.rowError.set({ id: claim.id, message: CLOSED });
      return;
    }
    if (claim.status !== 'DRAFT') {
      this.reset();
      this.rowError.set({ id: claim.id, message: NOT_DRAFT });
      return;
    }
    this.editingId.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.corrects.set(claim.corrects === null ? '' : String(claim.corrects));
    this.error.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.amount.set('');
    this.date.set(this.session.today() ?? '');
    this.note.set('');
    this.corrects.set('');
    this.error.set(null);
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.saving) return;
    this.error.set(null);
    const fields = { amount: this.amount().trim(), date: this.date(), note: this.note(), corrects: this.corrects().trim() };
    if (!CLAIM_AMOUNT.test(fields.amount)) {
      this.error.set('Enter an amount with at most two decimals.');
      return;
    }
    if (isCorrection(fields)) {
      // Whether it names a settled claim of this person is the store's to say, as the screen may be out of date.
      if (!CLAIM_NUMBER.test(fields.corrects)) {
        this.error.set(NOT_CORRECTING);
        return;
      }
    } else {
      fields.corrects = '';
    }
    if (this.periods.closedOn(fields.date || (this.session.today() ?? ''))) {
      this.error.set(CLOSED);
      return;
    }
    if (retiredOn({ retiredFrom: this.retiredFrom() }, fields.date || (this.session.today() ?? ''))) {
      this.error.set(RETIRED);
      return;
    }
    const id = this.editingId();
    this.saving = true;
    try {
      if (id === null) {
        await this.claims.add(this.personId(), fields);
      } else {
        await this.claims.update(id, fields);
      }
      this.reset();
    } catch (e) {
      this.error.set(e instanceof HttpErrorResponse && e.status === 423
        ? CLOSED
        : e instanceof HttpErrorResponse && e.status === 409
        ? NOT_DRAFT
        : e instanceof HttpErrorResponse && e.status === 422
        ? isCorrection(fields) ? NOT_CORRECTING : RETIRED
        : id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
    } finally {
      this.saving = false;
    }
  }
}

